options.getOption:
// Every scene the catalogue has over your area, as a dot on the calendar: up
// is cloudier, bigger covers more of the area. In colour, the scenes the
// "Cloud ≤" and "Covers ≥" cuts keep; in grey, the ones they leave out, so the
// chart shows what the cut costs. The dashed line is the cloud cut. The
// orange dot is the scene the map draws: the one picked, or, before any pick,
// the clearest one in range (the map's own default).
//
// Clicking a coloured dot picks that scene, as a row of the contact sheet
// does: it writes the scene (SCENE) and the centre of what it sees of your area
// (LAT, LNG), and the map flies there and draws it. Clicking the picked scene
// again clears the three, and the clearest scene comes back.
// The query frame has columns `acquired`, `scene_id`, `cloud_cover`,
// `covers_pct`, `usable`, `centre_lat`, `centre_lng` and `scene_url`.
// @constants begin
const SCENE = 'scene';
const LAT = 'lat';
const LNG = 'lng';
const CLOUD = 'cloud';
const SIZE = [7, 22];
const CONTEXT = 'rgba(128,128,128,0.45)';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;
const PICKED = theme.visualization.getColorByName('orange');
const USABLE = theme.visualization.getColorByName('blue');

const frame = context.panel.data.series.find((f) => f.refId === 'A') ?? context.panel.data.series[0];
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const num = (v) => (v == null ? null : Number(v));
const urls = col('scene_url');
const scenes = col('acquired').map((t, i) => ({
  time: Number(t),
  id: col('scene_id')[i],
  cloud: num(col('cloud_cover')[i]),
  covers: num(col('covers_pct')[i]) ?? 0,
  usable: col('usable')[i] === true || col('usable')[i] === 'true',
  lat: col('centre_lat')[i],
  lng: col('centre_lng')[i],
  url: urls[i],
}));
// The map's default when nothing is picked: the clearest usable scene.
const clearest = scenes.filter((s) => s.usable).sort((a, b) => a.cloud - b.cloud)[0] ?? null;

const readScene = () => {
  const fromUrl = new URLSearchParams(location.getLocation().search).get('var-' + SCENE);
  return fromUrl ?? context.grafana.replaceVariables('${' + SCENE + '}');
};
const shownBy = (picked) => (picked ? scenes.find((s) => s.url === picked) ?? null : clearest);

const size = (covers) => SIZE[0] + (SIZE[1] - SIZE[0]) * Math.sqrt(Math.max(0, Math.min(100, covers)) / 100);
const when = (ms) => new Date(ms).toISOString().slice(0, 16).replace('T', ' ') + ' UTC';

// The nearest usable dot to the pointer, within its own radius and a margin.
const onClick = (event) => {
  let best = null;
  for (const s of scenes) {
    if (!s.usable) continue;
    const [x, y] = chart.convertToPixel({ gridIndex: 0 }, [s.time, s.cloud ?? 0]);
    const d = Math.hypot(x - event.offsetX, y - event.offsetY);
    if (d <= size(s.covers) / 2 + 6 && (!best || d < best.d)) best = { s, d };
  }
  if (!best) {
    return;
  }
  const same = best.s.url === readScene();
  location.partial(
    {
      ['var-' + SCENE]: same ? '' : best.s.url,
      ['var-' + LAT]: same ? '' : String(best.s.lat),
      ['var-' + LNG]: same ? '' : String(best.s.lng),
    },
    true
  );
};
const zr = chart.getZr();
zr.on('click', onClick);

const cut = Number(context.grafana.replaceVariables('${' + CLOUD + '}'));
const span = scenes.length ? [scenes[0].time, scenes[scenes.length - 1].time] : null;
const pad = span ? Math.max((span[1] - span[0]) * 0.04, 86400000) : 0;

const build = (picked) => {
  const shown = shownBy(picked);
  const point = (s) => ({
    value: [s.time, s.cloud, s.covers],
    symbolSize: size(s.covers),
    itemStyle: {
      color: s === shown ? PICKED : s.usable ? USABLE : CONTEXT,
      opacity: s === shown || !s.usable ? 1 : picked ? 0.55 : 0.85,
      borderColor: s === shown ? text : 'transparent',
      borderWidth: s === shown ? 1.5 : 0,
    },
    label:
      s === shown
        ? { show: true, position: 'top', color: text, fontSize: 11, formatter: () => (picked ? 'picked' : 'clearest') }
        : { show: false },
  });
  return {
    animation: false,
    backgroundColor: 'transparent',
    grid: { left: 8, right: 16, top: 30, bottom: 8, containLabel: true },
    tooltip: {
      trigger: 'item',
      formatter: (p) => {
        const s = scenes[p.dataIndex];
        const state = !s.usable
          ? 'left out by Cloud ≤ or Covers ≥'
          : s.url === picked
            ? 'on the map · click to clear'
            : s === shown
              ? 'on the map (clearest) · click to fly to it'
              : 'click to draw it on the map';
        return `<b>${when(s.time)}</b><br/>${s.id}<br/>Cloud: <b>${s.cloud == null ? '?' : s.cloud.toFixed(1)} %</b> · covers <b>${s.covers.toFixed(0)} %</b> of your area<br/><span style="color:${muted}">${state}</span>`;
      },
    },
    xAxis: {
      type: 'time',
      min: span ? span[0] - pad : undefined,
      max: span ? span[1] + pad : undefined,
      axisLabel: { color: muted, hideOverlap: true },
      axisLine: { lineStyle: { color: muted } },
      splitLine: { show: false },
    },
    yAxis: {
      type: 'value',
      name: 'cloud %',
      min: 0,
      max: 100,
      interval: 25,
      nameTextStyle: { color: muted },
      axisLabel: { color: muted },
      splitLine: { lineStyle: { opacity: 0.15 } },
    },
    series: [
      {
        type: 'scatter',
        name: 'Scenes',
        data: scenes.map(point),
        markLine:
          cut < 100
            ? {
                silent: true,
                symbol: 'none',
                label: { formatter: `cloud ≤ ${cut} %`, color: muted, fontSize: 10, position: 'insideEndTop' },
                lineStyle: { type: 'dashed', color: muted },
                data: [{ yAxis: cut }],
              }
            : { data: [] },
      },
    ],
  };
};

// A pick changes only the scene, which this panel's query does not read: the
// orange dot is redrawn from the URL.
let drawn = readScene();
const stop = location.getHistory().listen(() => {
  const picked = readScene();
  if (picked !== drawn && !chart.isDisposed()) {
    drawn = picked;
    chart.setOption(build(picked), { replaceMerge: ['series'] });
  }
});

return {
  version: 2,
  option: build(readScene()),
  unsubscribe: () => {
    stop();
    zr.off('click', onClick);
  },
};

visualEditor.code:
return {
  dataset: context.editor.dataset,
  series: context.editor.series,
  xAxis: {
    type: 'time',
  },
  yAxis: {
    type: 'value',
    min: 'dataMin',
  },
}
